# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs, factor=3):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(digest(emit(shape(raw))))

