        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'total': 27, 'ratio': 1.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 15, 'ratio': 1.0})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 3, 'ratio': 0.333})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 12, 'ratio': 1.333})
